import {catalog,route,defaultBudget,escapeHTML as esc,modelPlan} from './core.js';
import {createCard} from './cards.js';
const $=s=>document.querySelector(s);
const workspace=$('#workspace'),input=$('#query'),list=$('#suggestions'),conversation=$('#conversation');
const state={profile:{},budget:{...defaultBudget},shortlist:new Set(),words:new Set()};
let bus=new EventTarget();let mode='idle',selected=-1,visible=[],searchTimer,composing=false,currentCategory=null,activeJob=null,hasHistory=false;
const templates=new Set();
const schoolsPromise=fetch('./schools.json').then(r=>{if(!r.ok)throw Error('学校资料加载失败');return r.json()}).catch(()=>null);
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),2400);}
function setMode(next){mode=next;const chat=next==='chat',explore=next==='explore';workspace.classList.toggle('chat',chat);workspace.classList.toggle('explore',explore);document.body.classList.toggle('chatting',chat);$('.chat-header').hidden=!chat;conversation.hidden=!chat;$('.chat-footnote').hidden=!chat;$('#suggestions-wrap').hidden=chat;$('#suggestions-wrap').inert=!explore;$('#quick-nav').hidden=chat;$('#quick-nav').inert=chat;$('#resume').hidden=!hasHistory;$('#quick-more').hidden=true;$('[data-browse]').setAttribute('aria-expanded','false');input.setAttribute('aria-expanded',String(explore));input.setAttribute('role',chat?'textbox':'combobox');input.removeAttribute('aria-activedescendant');input.placeholder=chat?'继续说说，或者调整上面的卡片…':'去日本留学，一年需要多少钱？';$('#clear-input').hidden=!input.value;$('#submit').setAttribute('aria-label',activeJob?'停止生成':'发送问题');}
function renderSuggestions(value='',all=false){const matches=all?catalog:route(value);visible=matches.length?matches:catalog;selected=-1;list.replaceChildren();$('#suggestion-label').textContent=all||!value?'从你在意的事开始':matches.length?'这件事，可以这样开始':'还不确定你的方向，选一张卡开始';$('#suggestion-count').textContent=`${visible.length} 张需求卡`;visible.forEach((c,i)=>{const b=document.createElement('button');b.type='button';b.className='suggestion';b.id='suggestion-'+i;b.setAttribute('role','option');b.setAttribute('aria-selected','false');b.style.setProperty('--i',Math.min(i,6));b.innerHTML=`<span class="suggestion-icon">${c.icon}</span><span class="suggestion-copy"><strong>${c.title}</strong><small>${c.tag}</small></span><span class="arrow">↗</span>`;b.onclick=()=>launch(c.id,input.value.trim()||c.prompt);list.append(b);});if(hasHistory){const b=document.createElement('button');b.type='button';b.className='resume-row';b.textContent='继续刚才的对话 ↗';b.onclick=()=>{setMode('chat');scrollBottom();};list.append(b);}$('#live').textContent=`${visible.length} 个留学需求栏目`;
}
function explore(all=false){if(mode==='chat')return;if(!input.value.trim()){setMode('idle');return;}setMode('explore');renderSuggestions(input.value.trim(),all);}
function scrollBottom(){requestAnimationFrame(()=>conversation.scrollTo({top:conversation.scrollHeight,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'}));}
function addUser(text){const m=document.createElement('div');m.className='message user';const b=document.createElement('div');b.className='user-bubble';b.textContent=text;m.append(b);conversation.append(m);}
function cancelJob(){if(!activeJob)return;activeJob.cancelled=true;clearTimeout(activeJob.timer);activeJob.skeleton.replaceWith(Object.assign(document.createElement('p'),{className:'card-note',textContent:'已停止。这一步没有生成卡片，你可以换个问题继续。'}));activeJob=null;$('#submit').textContent='↑';$('#submit').setAttribute('aria-label','发送问题');}
function reset(){cancelJob();conversation.replaceChildren();bus=new EventTarget();hasHistory=false;currentCategory=null;input.value='';setMode('idle');input.focus();toast('已开始新对话，当前页面偏好仍保留');}
async function launch(id,text){const item=catalog.find(c=>c.id===id);if(!item)return;cancelJob();clearTimeout(searchTimer);currentCategory=id;hasHistory=true;setMode('chat');addUser(text||item.prompt);input.value='';$('#clear-input').hidden=true;$('#context-label').textContent=`KAME · ${item.label}`;
 const message=document.createElement('div');message.className='message assistant';message.innerHTML=`<div class="assistant-label">KAME · 交互预览</div><p class="assistant-intro"></p>`;message.querySelector('p').textContent=item.intro;const skeleton=document.createElement('div');skeleton.className='skeleton';skeleton.setAttribute('aria-busy','true');skeleton.innerHTML=`<div class="skeleton-head"><i class="spinner"></i><span>正在展开${esc(item.label)}卡…</span></div><div class="skeleton-line" style="width:55%"></div><div class="skeleton-line" style="width:80%"></div><div class="skeleton-grid"><i></i><i></i></div>`;message.append(skeleton);conversation.append(message);scrollBottom();const job={cancelled:false,skeleton};activeJob=job;$('#submit').textContent='■';$('#submit').setAttribute('aria-label','停止生成');
 job.timer=setTimeout(async()=>{try{let data=[];if(['schools','compare','reviews'].includes(id)){data=await schoolsPromise;if(!data)throw Error('学校资料暂时没有加载成功，请刷新页面重试。');}if(job.cancelled)return;const card=createCard(id,{state,query:text,schoolData:data,bus,toast,launch});skeleton.replaceWith(card);templates.add(id);$('#live').textContent=`${item.label}卡已展开`;scrollBottom();}catch(e){if(job.cancelled)return;skeleton.innerHTML='';const p=document.createElement('p');p.className='card-note';p.textContent=e.message||'卡片暂时无法展开，请重试。';const retry=document.createElement('button');retry.className='secondary';retry.textContent='重新展开';retry.onclick=()=>launch(id,text);skeleton.append(p,retry);}finally{if(activeJob===job){activeJob=null;$('#submit').textContent='↑';$('#submit').setAttribute('aria-label','发送问题');}}},templates.has(id)?120:650);
}
input.addEventListener('focus',()=>{if(mode!=='chat')explore();});input.addEventListener('input',()=>{selected=-1;input.removeAttribute('aria-activedescendant');$('#clear-input').hidden=!input.value;if(composing||mode==='chat')return;clearTimeout(searchTimer);searchTimer=setTimeout(()=>explore(),80);});input.addEventListener('compositionstart',()=>{composing=true;clearTimeout(searchTimer);});input.addEventListener('compositionend',()=>{composing=false;if(mode!=='chat')explore();});
input.addEventListener('keydown',e=>{if(e.isComposing)return;if(mode==='explore'&&['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();selected=(selected+(e.key==='ArrowDown'?1:-1)+visible.length)%visible.length;[...list.querySelectorAll('[role=option]')].forEach((b,i)=>b.setAttribute('aria-selected',String(i===selected)));input.setAttribute('aria-activedescendant','suggestion-'+selected);list.children[selected]?.scrollIntoView({block:'nearest'});}if(e.key==='Escape'){e.preventDefault();setMode('idle');input.blur();}});
$('#composer').onsubmit=e=>{e.preventDefault();if(composing)return;if(activeJob){cancelJob();return;}const q=input.value.trim();if(!q){if(mode!=='chat')explore(true);return;}const matches=route(q);if(mode!=='chat'){if(selected>=0){launch(visible[selected].id,q);return;}if(!matches.length){explore(true);return;}launch(matches[0].id,q);}else if(matches.length)launch(matches[0].id,q);else if(currentCategory){addUser(q);input.value='';$('#clear-input').hidden=true;const m=document.createElement('div');m.className='message assistant';m.innerHTML='<div class="assistant-label">KAME · 交互预览</div><p class="assistant-intro"></p>';m.querySelector('p').textContent='这段自由问答会在接入模型后处理。现在可以直接调整卡片中的选项，或选择下面的需求继续体验。';const f=document.createElement('div');f.className='followups';for(const c of catalog.slice(0,4)){const b=document.createElement('button');b.textContent=c.label;b.onclick=()=>launch(c.id,c.prompt);f.append(b);}m.append(f);conversation.append(m);scrollBottom();}};
$('#clear-input').onclick=()=>{input.value='';input.focus();$('#clear-input').hidden=true;if(mode!=='chat')explore();};$('#minimize').onclick=()=>{setMode('idle');input.blur();};$('#new-chat').onclick=reset;
$('#quick-nav').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='resume'){setMode('chat');scrollBottom();return;}if(b.hasAttribute('data-browse')){const open=$('#quick-more').hidden;$('#quick-more').hidden=!open;b.setAttribute('aria-expanded',String(open));return;}const c=catalog.find(c=>c.id===b.dataset.category);launch(c.id,input.value.trim()||c.prompt);};
$('#quick-more').onclick=e=>{const b=e.target.closest('[data-category]');if(b){const c=catalog.find(c=>c.id===b.dataset.category);launch(c.id,c.prompt);}};
document.addEventListener('pointerdown',e=>{if(mode==='explore'&&!workspace.contains(e.target)){setMode('idle');input.blur();}});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();input.focus();}if(e.key==='Escape'&&e.target!==input){setMode('idle');input.blur();}});
if(window.visualViewport){const update=()=>document.documentElement.style.setProperty('--keyboard-inset',Math.max(0,innerHeight-visualViewport.height-visualViewport.offsetTop)+'px');visualViewport.addEventListener('resize',update);visualViewport.addEventListener('scroll',update);}
setMode('idle');
